import { loadFont } from "@remotion/google-fonts/PlusJakartaSans";
import React from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";

// PISCINOU. Motion vertical de vendas do aplicativo de gestão para piscineiros (piscinou.com).
// A locução gravada (src/voz-v1.mp3, 41,5 s) começa em "Conheça o Piscinou!": o gancho e o problema da copy não foram gravados.
// Identidade: o cliente não mandou logo nem cores. A marca vai escrita como no site ("piscinou."), e a paleta é escolha minha
// (azul de piscina + marinho sobre branco). As telas do aplicativo são desenhadas e ilustrativas, com nomes e valores fictícios.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica no celular, nos cartões e nos ícones.
// Tempos = tempos da locução (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const PSC_FPS = 30;
const LEAD = 0.2;
export const PSC_FRAMES = Math.round(42.4 * PSC_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
// impulso curto que volta a zero (o objeto "sente" a entrada)
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const WHITE = "#FFFFFF";
const NAVY = "#0A2540";
const AQUA = "#10B4E6";
const AQUA_D = "#0A8FCB";
const MIST = "#EAF7FD";
const LINE = "#DCE8F1";
const GREY = "#8A9BB0";
const GREEN = "#17A34A";
const AMBER = "#F59E0B";
const RED = "#E5484D";
const SHADOW = "0 30px 70px rgba(10,37,64,0.16), 0 4px 14px rgba(10,37,64,0.08)";

// trocas de cena
const T2 = 5.3, T3 = 12.5, T4 = 20.55, T5 = 26.95, T6 = 32.2, T7 = 35.45;

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 12).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

// linhas de título; a linha de destaque vem numa faixa de cor chapada
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlBg?: string; hlColor?: string }> = ({ t, items, size, top, color = NAVY, out, hlBg = AQUA, hlColor = WHITE }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.12 }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.04em", whiteSpace: "nowrap", color: hl ? hlColor : color, ...(hl ? { background: hlBg, padding: `${size * 0.05}px ${size * 0.28}px ${size * 0.12}px`, borderRadius: size * 0.26 } : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// marca escrita como no site: minúsculas com ponto
const Wordmark: React.FC<{ size: number; color?: string; dot?: string; dotScale?: number }> = ({ size, color = NAVY, dot = AQUA, dotScale = 1 }) => (
  <div style={{ fontFamily: F, fontWeight: 800, fontSize: size, letterSpacing: "-0.055em", lineHeight: 1, color, whiteSpace: "nowrap", display: "flex", alignItems: "baseline" }}>
    piscinou
    <span style={{ display: "inline-block", width: size * 0.17, height: size * 0.17, borderRadius: size, background: dot, marginLeft: size * 0.03, transform: `scale(${dotScale.toFixed(3)})` }} />
  </div>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string }>;
const sv = (s: number, c: string, ch: React.ReactNode) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoCal: Ico = ({ s, c }) => sv(s, c, <><rect x="3.5" y="5" width="17" height="15.5" rx="3" /><path d="M3.5 10h17M8 3v4M16 3v4" /></>);
const IcoUsers: Ico = ({ s, c }) => sv(s, c, <><circle cx="9" cy="8.5" r="3.5" /><path d="M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.900 6.500 5.500M16 5.300a3.500 3.500 0 010 6.400M18.500 14.900c1.700.800 2.700 2.500 3 5.100" /></>);
const IcoChart: Ico = ({ s, c }) => sv(s, c, <path d="M4 20V11M10 20V5M16 20v-7M21.500 20H2.500" />);
const IcoCheck: Ico = ({ s, c }) => sv(s, c, <path d="M5 12.500l4.500 4.500L19 7.500" />);
const IcoClock: Ico = ({ s, c }) => sv(s, c, <><circle cx="12" cy="12" r="8.500" /><path d="M12 7.500V12l3 2" /></>);
const IcoAlert: Ico = ({ s, c }) => sv(s, c, <><circle cx="12" cy="12" r="8.500" /><path d="M12 7.500v5.500M12 16.300v.200" /></>);
const IcoBadge: Ico = ({ s, c }) => sv(s, c, <><path d="M12 3l2.300 1.700 2.900-.100.800 2.800 2.400 1.600-1 2.700 1 2.700-2.400 1.600-.800 2.800-2.900-.100L12 21l-2.300-1.700-2.900.100-.800-2.800-2.400-1.600 1-2.700-1-2.700 2.400-1.600.800-2.800 2.900.100z" /><path d="M8.800 12.300l2.200 2.200 4.200-4.400" /></>);
const IcoSearch: Ico = ({ s, c }) => sv(s, c, <><circle cx="10.500" cy="10.500" r="6.500" /><path d="M15.500 15.500L21 21" /></>);

// ───────── celular e telas ilustrativas ─────────
const Phone: React.FC<{ w: number; children: React.ReactNode }> = ({ w, children }) => {
  const h = w * 2.02;
  return (
    <div style={{ width: w, height: h, borderRadius: w * 0.15, background: NAVY, padding: w * 0.028, boxSizing: "border-box", boxShadow: "0 50px 100px rgba(6,24,44,0.32), 0 8px 22px rgba(6,24,44,0.18)" }}>
      <div style={{ width: "100%", height: "100%", borderRadius: w * 0.125, background: WHITE, overflow: "hidden", position: "relative" }}>
        {children}
        <div style={{ position: "absolute", left: "50%", top: w * 0.03, width: w * 0.26, height: w * 0.06, marginLeft: -w * 0.13, borderRadius: w, background: NAVY }} />
      </div>
    </div>
  );
};
const Head: React.FC<{ u: number; title: string }> = ({ u, title }) => (
  <div style={{ position: "absolute", left: u * 7, right: u * 7, top: u * 15, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
    <span style={{ fontFamily: F, fontWeight: 800, fontSize: u * 8.4, color: NAVY, letterSpacing: "-0.04em" }}>{title}</span>
    <Wordmark size={u * 4.6} />
  </div>
);
const row = (u: number): React.CSSProperties => ({ position: "absolute", left: u * 7, right: u * 7, borderRadius: u * 4, background: WHITE, border: `${u * 0.35}px solid ${LINE}`, boxSizing: "border-box", display: "flex", alignItems: "center", fontFamily: F });
const Avatar: React.FC<{ u: number; s: number; n: string; c: string }> = ({ u, s, n, c }) => (
  <div style={{ width: u * s, height: u * s, borderRadius: u * s, background: c, color: WHITE, fontFamily: F, fontWeight: 800, fontSize: u * s * 0.4, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{n}</div>
);
const PEOPLE: [string, string, string][] = [["Carlos M.", "CM", AQUA], ["Ana P.", "AP", "#7C6CF2"], ["João S.", "JS", "#F2994A"], ["Marta L.", "ML", "#27AE82"], ["Rui T.", "RT", "#E5687A"]];

// início: três atalhos
const ScrHome: React.FC<{ u: number; t: number; at: number }> = ({ u, t, at }) => (
  <>
    <Head u={u} title="Hoje" />
    {([["Agenda", IcoCal, AQUA], ["Clientes", IcoUsers, "#7C6CF2"], ["Mensalidades", IcoChart, GREEN]] as [string, Ico, string][]).map(([n, I, c], i) => {
      const e = pop(t, at + i * 0.22, 0.5);
      return (
        <div key={n} style={{ ...row(u), top: u * (34 + i * 37), height: u * 32, padding: `0 ${u * 6}px`, gap: u * 5, opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * u * 14).toFixed(1)}px)` }}>
          <div style={{ width: u * 18, height: u * 18, borderRadius: u * 5, background: c, display: "flex", alignItems: "center", justifyContent: "center" }}><I s={u * 10.5} c={WHITE} /></div>
          <div>
            <div style={{ fontWeight: 800, fontSize: u * 6.6, color: NAVY, letterSpacing: "-0.03em" }}>{n}</div>
            <div style={{ width: u * (30 - i * 5), height: u * 2.6, borderRadius: u, background: LINE, marginTop: u * 2.4 }} />
          </div>
        </div>
      );
    })}
    <div style={{ position: "absolute", left: u * 7, right: u * 7, top: u * 148, height: u * 30, borderRadius: u * 4, background: MIST }} />
  </>
);
// agenda: dias da semana e visitas do dia
const ScrAgenda: React.FC<{ u: number; t: number; at: number }> = ({ u, t, at }) => (
  <>
    <Head u={u} title="Agenda" />
    <div style={{ position: "absolute", left: u * 7, right: u * 7, top: u * 32, display: "flex", justifyContent: "space-between" }}>
      {["S", "T", "Q", "Q", "S", "S"].map((d, i) => {
        const on = i === 2;
        return (
          <div key={i} style={{ width: u * 12.4, height: u * 17, borderRadius: u * 4, background: on ? AQUA : MIST, color: on ? WHITE : GREY, fontFamily: F, fontWeight: 800, fontSize: u * 5.4, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", transform: `scale(${on ? (1 + 0.14 * bump(t, at + 0.15, 0.5)).toFixed(3) : 1})` }}>
            <span style={{ fontSize: u * 3.6, fontWeight: 600 }}>{d}</span>{12 + i}
          </div>
        );
      })}
    </div>
    {["08:00", "10:30", "13:00", "15:30", "17:00"].map((h, i) => {
      const e = pop(t, at + 0.12 + i * 0.13, 0.45);
      return (
        <div key={h} style={{ ...row(u), top: u * (56 + i * 26), height: u * 22, padding: `0 ${u * 5}px`, gap: u * 4.5, opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * u * 26).toFixed(1)}px)` }}>
          <span style={{ fontWeight: 800, fontSize: u * 5.4, color: AQUA_D, width: u * 17 }}>{h}</span>
          <div style={{ width: u * 0.8, height: u * 12, borderRadius: u, background: PEOPLE[i][2] }} />
          <div>
            <div style={{ fontWeight: 700, fontSize: u * 5.6, color: NAVY, letterSpacing: "-0.02em" }}>{PEOPLE[i][0]}</div>
            <div style={{ width: u * (26 - (i % 3) * 5), height: u * 2.4, borderRadius: u, background: LINE, marginTop: u * 2 }} />
          </div>
        </div>
      );
    })}
  </>
);
// clientes: lista e um cliente novo entrando no topo
const ScrClients: React.FC<{ u: number; t: number; at: number }> = ({ u, t, at }) => {
  const add = pop(t, at + 0.55, 0.5);
  return (
    <>
      <Head u={u} title="Clientes" />
      {PEOPLE.map(([n, ini, c], i) => {
        const novo = i === 0;
        const e = novo ? add : pop(t, at + 0.05 + i * 0.09, 0.4);
        return (
          <div key={n} style={{ ...row(u), top: u * (34 + i * 27), height: u * 23, padding: `0 ${u * 5}px`, gap: u * 4.5, opacity: Math.min(1, e * 2), transform: `scale(${(0.8 + 0.2 * e).toFixed(3)})`, ...(novo ? { borderColor: AQUA, background: MIST } : {}) }}>
            <Avatar u={u} s={13} n={ini} c={c} />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: u * 5.8, color: NAVY, letterSpacing: "-0.02em" }}>{n}</div>
              <div style={{ width: u * (30 - (i % 3) * 6), height: u * 2.4, borderRadius: u, background: LINE, marginTop: u * 2 }} />
            </div>
            {novo ? <span style={{ fontWeight: 800, fontSize: u * 3.8, color: WHITE, background: AQUA, borderRadius: u * 3, padding: `${u * 1.2}px ${u * 2.6}px` }}>novo</span> : null}
          </div>
        );
      })}
      <div style={{ position: "absolute", right: u * 8, top: u * 168, width: u * 19, height: u * 19, borderRadius: u * 19, background: AQUA, color: WHITE, fontFamily: F, fontWeight: 600, fontSize: u * 13, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center", paddingBottom: u * 1.4, boxSizing: "border-box", transform: `scale(${(pop(t, at + 0.2) * (1 + 0.25 * bump(t, at + 0.5, 0.35))).toFixed(3)})` }}>+</div>
    </>
  );
};
// financeiro: total do mês, barras e situação das mensalidades
const ScrFin: React.FC<{ u: number; t: number; at: number; pills: number }> = ({ u, t, at, pills }) => {
  const g = k(t, at + 0.4, 2.2);
  return (
    <>
      <Head u={u} title="Financeiro" />
      <div style={{ position: "absolute", left: u * 7, right: u * 7, top: u * 33, height: u * 38, borderRadius: u * 5, background: NAVY, padding: `${u * 5.5}px ${u * 6}px`, boxSizing: "border-box", fontFamily: F }}>
        <div style={{ fontWeight: 600, fontSize: u * 4.4, color: "#9FC3DD" }}>Recebido no mês</div>
        <div style={{ fontWeight: 800, fontSize: u * 12.5, color: WHITE, letterSpacing: "-0.04em", marginTop: u * 1.5 }}>R$ {Math.round(4850 * g).toLocaleString("pt-BR")}</div>
      </div>
      <div style={{ position: "absolute", left: u * 7, right: u * 7, top: u * 77, height: u * 62, borderRadius: u * 5, background: MIST, display: "flex", alignItems: "flex-end", justifyContent: "space-between", padding: `0 ${u * 6}px ${u * 6}px`, boxSizing: "border-box" }}>
        {[0.42, 0.58, 0.5, 0.72, 0.66, 0.92].map((v, i) => (
          <div key={i} style={{ width: u * 8.6, height: u * 48 * v * k(t, at + 0.25 + i * 0.28, 0.8), borderRadius: u * 2.4, background: i === 5 ? AQUA : "#A9DDF3" }} />
        ))}
      </div>
      {([["Pagas", "18", GREEN], ["A vencer", "5", AMBER], ["Pendentes", "4", RED]] as const).map(([n, v, c], i) => {
        const e = pop(t, pills + i * 0.16, 0.45);
        return (
          <div key={n} style={{ ...row(u), top: u * (146 + i * 0), left: u * (7 + i * 29.2), right: "auto", width: u * 27.2, height: u * 36, flexDirection: "column", justifyContent: "center", gap: u * 1.2, opacity: Math.min(1, e * 2), transform: `scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>
            <span style={{ fontWeight: 800, fontSize: u * 10, color: c, letterSpacing: "-0.04em" }}>{v}</span>
            <span style={{ fontWeight: 700, fontSize: u * 3.7, color: NAVY }}>{n}</span>
          </div>
        );
      })}
    </>
  );
};
const Note: React.FC<{ o: number; color?: string; top?: number }> = ({ o, color = GREY, top = 1750 }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: F, fontWeight: 500, fontSize: 28, color, opacity: o, letterSpacing: "0.01em" }}>telas ilustrativas</div>
);

// ───────── cena 1 · a marca: duas batidas de tela cheia e a apresentação com o aplicativo subindo ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  if (t < 0.66) {
    const e = k(t, -0.3, 0.4);
    return (
      <AbsoluteFill style={{ background: NAVY, alignItems: "center", justifyContent: "center" }}>
        <div style={{ fontFamily: F, fontWeight: 800, fontSize: 170, color: WHITE, letterSpacing: "-0.05em", transform: `scale(${(1.25 - 0.25 * e + 0.05 * lin(t, 0, 0.66)).toFixed(4)})` }}>Conheça</div>
      </AbsoluteFill>
    );
  }
  if (t < 1.7) {
    const e = pop(t, 0.66, 0.42);
    const ring = lin(t, 0.7, 1.7);
    return (
      <AbsoluteFill style={{ background: AQUA, alignItems: "center", justifyContent: "center" }}>
        {/* a onda que o ponto da marca faz na água */}
        <div style={{ position: "absolute", left: 540, top: 960, width: 0, height: 0 }}>
          <div style={{ position: "absolute", width: 300 + ring * 1500, height: 300 + ring * 1500, borderRadius: 3000, border: `${(10 * (1 - ring)).toFixed(1)}px solid ${WHITE}`, transform: "translate(-50%, -50%)", opacity: 0.55 * (1 - ring) }} />
        </div>
        <div style={{ transform: `scale(${(0.55 + 0.45 * e + 0.05 * lin(t, 0.66, 1.7)).toFixed(4)})` }}>
          <Wordmark size={186} color={WHITE} dot={NAVY} dotScale={pop(t, 0.95, 0.4)} />
        </div>
      </AbsoluteFill>
    );
  }
  const up = k(t, 1.75, 0.9);
  return (
    <AbsoluteFill style={{ background: WHITE }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 150, display: "flex", justifyContent: "center", ...blurIn(t, 1.7, undefined, 0.3) }}><Wordmark size={58} /></div>
      <Lines t={t} top={262} size={70} items={[["O aplicativo de gestão", 1.78], ["feito especialmente", 3.0], ["para piscineiros", 4.4, true]]} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 700, display: "flex", justifyContent: "center", transformOrigin: "540px 1200px", transform: `translateY(${((1 - up) * 1100 + Math.sin(t * 2.3) * 16).toFixed(1)}px) scale(${(0.88 + 0.16 * lin(t, 1.75, T2) + 0.03 * bump(t, 4.4)).toFixed(4)}) rotate(${((1 - up) * 6 + Math.sin(t * 1.9) * 1.6).toFixed(2)}deg)` }}>
        <Phone w={500}><ScrHome u={4.72} t={t} at={2.3} /></Phone>
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · agenda, clientes e painel financeiro: o mesmo celular, uma tela por batida ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const A = 6.2, B = 7.4, C = 8.95;
  const sl = io(t, B - 0.12, B + 0.3) + io(t, C - 0.12, C + 0.3);
  const u = 5.29, W = 560 - 560 * 0.056;
  const z = 0.92 + 0.15 * lin(t, T2, T3) + 0.04 * bump(t, B, 0.45) + 0.04 * bump(t, C, 0.45);
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <div style={{ position: "absolute", left: 540 - 700, top: 1040 - 700, width: 1400, height: 1400, borderRadius: 1400, background: `radial-gradient(circle, rgba(16,180,230,${(0.2 + 0.05 * Math.sin(t * 1.3)).toFixed(3)}) 0%, rgba(16,180,230,0) 62%)` }} />
      <Lines t={t} top={236} size={50} color="#9FC3DD" items={[["Com ele, você organiza", 5.42]]} out={8.7} />
      <Lines t={t} top={236} size={50} color="#9FC3DD" items={[["e você tem um", 8.92]]} />
      <Lines t={t} top={312} size={104} color={WHITE} items={[["sua agenda", A]]} out={B - 0.22} />
      <Lines t={t} top={312} size={104} color={WHITE} items={[["seus clientes", B]]} out={C - 0.22} />
      <Lines t={t} top={312} size={92} color={WHITE} hlColor={NAVY} items={[["painel financeiro", C, true]]} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 560, display: "flex", justifyContent: "center", transformOrigin: "540px 1400px", transform: `translateY(${((1 - k(t, T2, 0.7)) * 240 + Math.sin(t * 2.4) * 15).toFixed(1)}px) scale(${z.toFixed(4)}) rotate(${(Math.sin(t * 1.9) * 1.5).toFixed(2)}deg)` }}>
        <Phone w={560}>
          {[ScrAgenda, ScrClients].map((S, i) => (
            <div key={i} style={{ position: "absolute", inset: 0, transform: `translateX(${((i - sl) * W).toFixed(1)}px)` }}><S u={u} t={t} at={[T2 + 0.25, B][i]} /></div>
          ))}
          <div style={{ position: "absolute", inset: 0, transform: `translateX(${((2 - sl) * W).toFixed(1)}px)` }}><ScrFin u={u} t={t} at={C} pills={11.3} /></div>
        </Phone>
      </div>
      <Note o={k(t, C, 0.5) * 0.9} color="#7FA3BF" top={1790} />
    </AbsoluteFill>
  );
};

// ───────── cena 3 · mensalidades: um cartão por situação, o da frente sai e o próximo vem ─────────
const CARDS: { who: number; at: number; tag: number; out: number }[] = [
  { who: 0, at: T3, tag: 14.82, out: 16.05 },
  { who: 1, at: 16.05, tag: 17.3, out: 18.12 },
  { who: 3, at: 18.12, tag: 19.95, out: 99 },
];
const S3: React.FC<{ t: number }> = ({ t }) => {
  const paid = pop(t, 19.95, 0.5);
  return (
    <AbsoluteFill style={{ background: WHITE }}>
